#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> x(n);
    int h = 0;
    for (int i = 0; i < n; ++i) {
        cin >> x[i];
        if (x[i] > h) {
            h = x[i];
        }
    }

    for (int level = h; level >= 1; --level) {
        for (int i = 0; i < n; ++i) {
            if (x[i] >= level) {
                cout << 1;
            } else {
                cout << 0;
            }
            if (i < n - 1) {
                cout << ' ';
            }
        }
        cout << '\n';
    }

    return 0;
}
